def list_symbols():
    return sorted(SYMBOLS)

def get_svg(key):
    return SYMBOLS[key]["svg"]

def get_ports(key):
    return SYMBOLS[key]["ports"]

def get_frame(key):
    return SYMBOLS[key]["frame"]
